/**
 * Ticket #27 acceptance test — the contract for keeping small details the downscale vote erases.
 * Do not edit this file to make it pass.
 */
import { describe, expect, it } from 'vitest';
import { fitCells, type FitCellsOptions } from '../../scripts/lib/gemini-art';
import type { PngImage } from '../../scripts/lib/png';

type Pixel = readonly [number, number, number, number];
const CLEAR: Pixel = [0, 0, 0, 0];
const SKIN: Pixel = [252, 226, 202, 255];
const ROBE: Pixel = [242, 234, 241, 255];
const HALO: Pixel = [238, 207, 155, 255];
const EYE: Pixel = [20, 27, 27, 255];

function canvas(width: number, height: number): PngImage {
  const data = Buffer.alloc(width * height * 4);
  for (let i = 0; i < width * height; i += 1) data.set(CLEAR, i * 4);
  return { width, height, data };
}

function rect(image: PngImage, x0: number, y0: number, w: number, h: number, p: Pixel): void {
  for (let y = y0; y < y0 + h; y += 1) for (let x = x0; x < x0 + w; x += 1) image.data.set(p, (y * image.width + x) * 4);
}

/**
 * One cell, sprite at (OX, OY): a 300 × 240 skin face over a 300 × 210 robe, so the region
 * is 300 × 450 and fits the 15 px feet box at exactly 30 source px per output pixel
 * (10 × 15 output px, placed at frame x 3, y 1). Two eyes, each 20 × 60 px with a 2 px
 * halo, straddle output columns 2|3 and 5|6 with 8 and 12 px, so the skin wins every
 * block they touch. Their centroids (92, 125) and (182, 125) sprite-local fall in output
 * pixels (3, 4) and (6, 4), i.e. frame pixels (6, 5) and (9, 5).
 */
const OX = 20;
const OY = 20;
function face(): PngImage {
  const image = canvas(340, 490);
  rect(image, OX, OY, 300, 240, SKIN);
  rect(image, OX, OY + 240, 300, 210, ROBE);
  for (const ex of [82, 172]) {
    rect(image, OX + ex - 2, OY + 95 - 2, 24, 64, HALO);
    rect(image, OX + ex, OY + 95, 20, 60, EYE);
  }
  return image;
}

const BASE: FitCellsOptions = { columns: 1, rows: 1, frameWidth: 16, frameHeight: 16, anchor: 'feet', share: 'column' };

function pixelsOf(sheet: PngImage, colour: Pixel): Array<[number, number]> {
  const found: Array<[number, number]> = [];
  for (let y = 0; y < sheet.height; y += 1) {
    for (let x = 0; x < sheet.width; x += 1) {
      const i = (y * sheet.width + x) * 4;
      if (sheet.data[i] === colour[0] && sheet.data[i + 1] === colour[1] && sheet.data[i + 2] === colour[2] && sheet.data[i + 3]! >= 128) {
        found.push([x, y]);
      }
    }
  }
  return found;
}

describe('#27 keep details', () => {
  it('today’s fit loses both eyes', () => {
    expect(pixelsOf(fitCells(face(), BASE), EYE)).toEqual([]);
  });

  it('keeps both eyes, one pixel each at the eye centroid', () => {
    expect(pixelsOf(fitCells(face(), { ...BASE, keepDetails: true }), EYE)).toEqual([
      [6, 5],
      [9, 5],
    ]);
  });

  it('keeps both eyes with alignment on too', () => {
    const eyes = pixelsOf(fitCells(face(), { ...BASE, keepDetails: true, align: true }), EYE);
    expect(eyes).toHaveLength(2);
    expect(eyes[0]![1]).toBe(eyes[1]![1]);
    expect(eyes[1]![0] - eyes[0]![0]).toBe(3);
  });

  it('changes only the eye pixels', () => {
    const plain = fitCells(face(), BASE);
    const kept = fitCells(face(), { ...BASE, keepDetails: true });
    let changed = 0;
    for (let i = 0; i < plain.data.length; i += 4) if (plain.data.compare(kept.data, i, i + 4, i, i + 4) !== 0) changed += 1;
    expect(changed).toBe(2);
  });

  it('leaves a detail that already shows, and a speck below the size bound, alone', () => {
    const image = canvas(340, 490);
    rect(image, OX, OY, 300, 240, SKIN);
    rect(image, OX, OY + 240, 300, 210, ROBE);
    rect(image, OX + 90, OY + 90, 30, 30, EYE); // one whole output pixel: the vote already keeps it
    rect(image, OX + 200, OY + 100, 6, 6, EYE); // 0.04 output px²: below the 0.4 bound
    const plain = fitCells(image, BASE);
    expect(Buffer.compare(fitCells(image, { ...BASE, keepDetails: true }).data, plain.data)).toBe(0);
  });

  it('is byte-identical with the option off', () => {
    const image = face();
    expect(Buffer.compare(fitCells(image, BASE).data, fitCells(image, { ...BASE, keepDetails: false }).data)).toBe(0);
  });
});
